const state = $getWorkflowStaticData('global');
state.processedEvents = state.processedEvents || {};
state.identities = state.identities || {};

const raw = $json.body ?? $json;
const clean = v => String(v ?? '').trim().replace(/\s+/g, ' ');
const normEmail = v => clean(v).toLowerCase();
const normPhone = v => {
  const s = clean(v);
  if (!s) return '';
  const digits = s.replace(/\D/g, '');
  return s.startsWith('+') ? '+' + digits : digits;
};

const eventId = clean(raw.event_id);
const email = normEmail(raw.email);
const phone = normPhone(raw.phone);

if (!eventId) {
  return [{json:{
    ok:false,
    status:'validation_failed',
    reason:'missing_event_id',
    autonomous_send:false,
    execution_id:$execution.id
  }}];
}
if (!email && !phone) {
  return [{json:{
    ok:false,
    status:'validation_failed',
    reason:'missing_identity',
    event_id:eventId,
    autonomous_send:false,
    execution_id:$execution.id
  }}];
}

if (state.processedEvents[eventId]) {
  return [{json:{
    ok:true,
    status:'idempotent_skip',
    event_id:eventId,
    seen_event:true,
    duplicate_identity:false,
    record_id:state.processedEvents[eventId].record_id,
    autonomous_send:false,
    execution_id:$execution.id
  }}];
}

const identities = [];
if (email) identities.push(`email:${email}`);
if (phone) identities.push(`phone:${phone}`);

const duplicateKey = identities.find(k => state.identities[k]);
if (duplicateKey) {
  const recordId = state.identities[duplicateKey].record_id;
  state.processedEvents[eventId] = {record_id:recordId, status:'duplicate_identity'};
  return [{json:{
    ok:true,
    status:'duplicate_identity_skip',
    event_id:eventId,
    seen_event:false,
    duplicate_identity:true,
    duplicate_key:duplicateKey,
    record_id:recordId,
    autonomous_send:false,
    execution_id:$execution.id
  }}];
}

state.sequence = (state.sequence || 0) + 1;
const recordId = `lead_${String(state.sequence).padStart(4,'0')}`;
state.processedEvents[eventId] = {record_id:recordId, status:'created'};
for (const identity of identities) {
  state.identities[identity] = {record_id:recordId, first_event_id:eventId};
}

return [{json:{
  ok:true,
  status:'created',
  event_id:eventId,
  seen_event:false,
  duplicate_identity:false,
  record_id:recordId,
  identities,
  autonomous_send:false,
  execution_id:$execution.id
}}];
